(5697746, 828189, 100820, '<td valign="top">this feels to me as though it needs something else in the frame for it to be complete, it seems a little plain here.  great capture in less than perfect lighting conditions though!</td>', 'this feels to me as though it needs something else in the frame for it to be complete, it seems a little plain here.  great capture in less than perfect lighting conditions though!', '2009-10-23 00:42:58.000000', NULL, 1),
(5697747, 828439, 69008, '<td valign="top">I think that I would have tried to change camera angle a little to the left to bring the stream in more from the upper right corner for this. The overcast sky is hurting this shot, but there is not much that can be done about it in basic editing.  Nice spot.</td>', 'I think that I would have tried to change camera angle a little to the left to bring the stream in more from the upper right corner for this. The overcast sky is hurting this shot, but there is not much that can be done about it in basic editing.  Nice spot.', '2009-10-23 00:44:34.000000', NULL, 1),
(5697748, 828796, 69008, '<td valign="top">Detail is almost lost in the shadow area of this shot. It''s quite contrasty with the bright back lighting.</td>', 'Detail is almost lost in the shadow area of this shot. It''s quite contrasty with the bright back lighting.', '2009-10-23 00:46:35.000000', NULL, 1),
(5697749, 828420, 69008, '<td valign="top">Pretty much a snapshot, but it is a happy one.</td>', 'Pretty much a snapshot, but it is a happy one.', '2009-10-23 00:47:28.000000', NULL, 1),
(5697750, 828367, 69008, '<td valign="top">Love the colors in the foreground. The top half of the shot with the water and wave not being distinct is hurting this one.</td>', 'Love the colors in the foreground. The top half of the shot with the water and wave not being distinct is hurting this one.', '2009-10-23 00:49:57.000000', NULL, 1),
