(5697755, 828436, 69008, '<td valign="top">I like the multiple reflections in the car in this.</td>', 'I like the multiple reflections in the car in this.', '2009-10-23 00:57:25.000000', NULL, 1),
(5697756, 828500, 69008, '<td valign="top">I think that this one is going to finish high in this challenge because it is just so unusual, with the massive fisheye effect, and the huge leading line in it.</td>', 'I think that this one is going to finish high in this challenge because it is just so unusual, with the massive fisheye effect, and the huge leading line in it.', '2009-10-23 00:59:31.000000', NULL, 1),
(5697757, 828431, 69008, '<td valign="top">Nice light in this shot, with the low angle sun making the shadows on  the ground this way.</td>', 'Nice light in this shot, with the low angle sun making the shadows on  the ground this way.', '2009-10-23 01:01:09.000000', NULL, 1),
(5697758, 828688, 69008, '<td valign="top">This is a nice candid slice of life sort of shot.</td>', 'This is a nice candid slice of life sort of shot.', '2009-10-23 01:02:25.000000', NULL, 1),
(5697759, 827942, 69008, '<td valign="top">At least not DNMC.  The highlight hurts in this one.  To get more even light, try reflecting the light off something, or using diffused light through a window with a thin shade for this sort of subject.</td>', 'At least not DNMC.  The highlight hurts in this one.  To get more even light, try reflecting the light off something, or using diffused light through a window with a thin shade for this sort of subject.', '2009-10-23 01:05:07.000000', NULL, 1),
(5697760, 828648, 69008, '<td valign="top">The trees are pretty dark in this shot. Maybe shooting shortly after sunrise or near sunset would make a nicer looking shot. I know that we can''t always wait for that light though.</td>', 'The trees are pretty dark in this shot. Maybe shooting shortly after sunrise or near sunset would make a nicer looking shot. I know that we can''t always wait for that light though.', '2009-10-23 01:07:08.000000', NULL, 1),
(5697762, 827766, 69008, '<td valign="top">Nice point of view. I wouldn''t want to be looking for a place to make an emergency landing in this area.</td>', 'Nice point of view. I wouldn''t want to be looking for a place to make an emergency landing in this area.', '2009-10-23 01:09:05.000000', NULL, 1),
(5697763, 828450, 69008, '<td valign="top">Beautiful shot, and nicely processed to get good contrast and tonal levels. It''s a pretty place too. I think that this will score high in this challenge.</td>', 'Beautiful shot, and nicely processed to get good contrast and tonal levels. It''s a pretty place too. I think that this will score high in this challenge.', '2009-10-23 01:10:47.000000', NULL, 1),
