(5697766, 828819, 69008, '<td valign="top">Pretty spot.</td>', 'Pretty spot.', '2009-10-23 01:13:01.000000', NULL, 1),
(5697768, 827886, 69008, '<td valign="top">Fortunate timing to get the rainbow for the challenge.  It looks like a grand location to live.</td>', 'Fortunate timing to get the rainbow for the challenge.  It looks like a grand location to live.', '2009-10-23 01:14:24.000000', NULL, 1),
(5697769, 827891, 69008, '<td valign="top">It''s the "Rock-Ness" monster!</td>', 'It''s the "Rock-Ness" monster!', '2009-10-23 01:14:53.000000', NULL, 1),
