(5697777, 828822, 69008, '<td valign="top">This connects because I know the sounds, scents, and how the clay feels when it piles up on the soles of your boots.</td>', 'This connects because I know the sounds, scents, and how the clay feels when it piles up on the soles of your boots.', '2009-10-23 01:20:01.000000', NULL, 1),
(5697779, 828603, 69008, '<td valign="top">POV helps here with the straight dock, and the curved line of reflection on the water leading to the end of the dock.</td>', 'POV helps here with the straight dock, and the curved line of reflection on the water leading to the end of the dock.', '2009-10-23 01:20:57.000000', NULL, 1),
(5697782, 828679, 69008, '<td valign="top">That''s a  really nice pond, and an excellent reflection.</td>', 'That''s a  really nice pond, and an excellent reflection.', '2009-10-23 01:22:34.000000', NULL, 1),
(5697785, 828704, 69008, '<td valign="top">You got a super clear day for this shot.</td>', 'You got a super clear day for this shot.', '2009-10-23 01:23:45.000000', NULL, 1),
(5697787, 828693, 69008, '<td valign="top">Good DOF, and interesting hazy light in this shot.  It''s almost over sharpened at this small size.</td>', 'Good DOF, and interesting hazy light in this shot.  It''s almost over sharpened at this small size.', '2009-10-23 01:25:59.000000', NULL, 1),
