INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5702751, 828748, 88580, '<td valign="top"><i>Very</i> nice low-key, minimal, abstract.</td>', 'Very nice low-key, minimal, abstract.', '2009-10-27 22:12:03.000000', NULL, 1),
(5702823, 828496, 56579, '<td valign="top">The photograph subject lacks interest.  Turning it B&amp;W does not make it interesting...the lighting makes the B&amp;W feel even more awkward to me.<br/> <br/>If I were to do this, I would probably get closer in to the bed.  For example only show the part of the bed I lay on, and the night stand.  That way the further dimmer ends are not as much as an issue.</td>', 'The photograph subject lacks interest.  Turning it B&W does not make it interesting...the lighting makes the B&W feel even more awkward to me. If I were to do this, I would probably get closer in to the bed.  For example only show the part of the bed I lay on, and the night stand.  That way the further dimmer ends are not as much as an issue.', '2009-10-27 23:22:53.000000', NULL, 1),
(5702827, 827942, 103142, '<td valign="top">I really like the idea, but your color seems a little off, the highlight at the top is distracting, and I''d really like a little more depth of field to cover the spot where the pin is.<br/> <br/>I do like the angle of the globe, and I like the shadow of the holder, just wish you could have softened the light so it didn''t have the blown area.</td>', 'I really like the idea, but your color seems a little off, the highlight at the top is distracting, and I''d really like a little more depth of field to cover the spot where the pin is. I do like the angle of the globe, and I like the shadow of the holder, just wish you could have softened the light so it didn''t have the blown area.', '2009-10-27 23:34:24.000000', NULL, 1),
(5702828, 828027, 103142, '<td valign="top">haha! lovely!</td>', 'haha! lovely!', '2009-10-27 23:35:09.000000', NULL, 1),
