(5797397, 828090, 65319, '<td valign="top">Deborah!  How could I miss this one...exceptionally STUNNING!  Well done!</td>', 'Deborah!  How could I miss this one...exceptionally STUNNING!  Well done!', '2010-01-05 18:03:47.000000', NULL, 0),
(5843905, 828794, 100831, '<td valign="top">Love it and i CANNOT believe this was taken in Staten Island. I guess this really is the forgotten borough.</td>', 'Love it and i CANNOT believe this was taken in Staten Island. I guess this really is the forgotten borough.', '2010-01-29 20:47:55.000000', NULL, 0),
