(5865895, 828136, 68504, '<td valign="top">Eloquent. Composition and restraint.</td>', 'Eloquent. Composition and restraint.', '2010-02-13 18:34:21.000000', NULL, 0),
(5866801, 828090, 38930, '<td valign="top">This is great!  I love taking pictures of this pier.  Are you from Ventura??</td>', 'This is great!  I love taking pictures of this pier.  Are you from Ventura??', '2010-02-14 19:17:46.000000', NULL, 0),
(5910776, 828029, 69008, '<td valign="top">At first glance, I thought the title was Tequesta sunrise.   Pretty colors in this shot. I probably have backed away from the little shack a ways to make it smaller in the composition. That would not work though, because it would lose the edge of the water on the beach unless you could go up as well as back.</td>', 'At first glance, I thought the title was Tequesta sunrise.   Pretty colors in this shot. I probably have backed away from the little shack a ways to make it smaller in the composition. That would not work though, because it would lose the edge of the water on the beach unless you could go up as well as back.', '2010-03-19 21:56:51.000000', NULL, 0),
(5992257, 828679, 117264, '<td valign="top">Very Beautiful, great depth and reflection</td>', 'Very Beautiful, great depth and reflection', '2010-05-05 13:01:30.000000', NULL, 0),
(6037020, 828367, 105079, '<td valign="top">I should let anyone who see''s this know, this had no window or dirt associated with it.  Some condensation.  I got this effect with a really fast shutter and the built in flash on my D200.  I as also literally spinning, it created the neat motion-y affect.</td>', 'I should let anyone who see''s this know, this had no window or dirt associated with it.  Some condensation.  I got this effect with a really fast shutter and the built in flash on my D200.  I as also literally spinning, it created the neat motion-y affect.', '2010-06-02 05:34:50.000000', NULL, 0),
(6182140, 828148, 38930, '<td valign="top">This is great - are you in Portland?</td>', 'This is great - are you in Portland?', '2010-10-05 18:29:29.000000', NULL, 0),
(6191790, 828679, 98339, '<td valign="top">What a beautifully clear day this was...nice peaceful reflection</td>', 'What a beautifully clear day this was...nice peaceful reflection', '2010-10-14 17:09:24.000000', NULL, 0),
